function model(p) {
  // An illustrative story: one push, one GitHub Actions workflow, one deploy. Durations are made up but in a realistic
  // range for a small Node project with browser tests. realMs = milliseconds after `git push`; start/dur = playback seconds.
  const toMain = Math.round(p.target) === 1, fails = Math.round(p.test) === 1, warm = Math.round(p.cache) === 1, protect = Math.round(p.protection) === 1;
  const S = 1000, MIN = 60000;
  const STEPS = [
    { id: 'checkout', name: 'Check out the commit', dur: 8, note: 'actions/checkout clones the repository at the pushed commit onto an empty virtual machine.' },
    { id: 'node', name: 'Set up Node', dur: 6, note: 'actions/setup-node installs the Node version the workflow names. The runner started with nothing.' },
    { id: 'install', name: 'npm ci', dur: warm ? 14 : 95, note: warm ? 'npm ci restores node_modules from the dependency cache, keyed on package-lock.json: 14 s.' : 'npm ci downloads every dependency from the registry, because nothing is cached yet: 95 s.' },
    { id: 'browser', name: 'Install Chromium', dur: warm ? 4 : 48, note: warm ? 'Playwright finds its browser in the cache and skips the download.' : 'Playwright downloads a Chromium build and the Linux libraries it needs: 48 s.' },
    { id: 'build', name: 'npm run build', dur: 20, note: 'The build assembles the page and the toolkit from the sources, exactly as on a laptop.' },
    { id: 'unit', name: 'Unit tests', dur: 25, note: fails ? 'One unit test fails: an assertion in test/unit/specs.test.mjs. The step exits 1.' : 'All unit tests pass. The step exits 0, so the job moves on.' },
    { id: 'e2e', name: 'Browser tests (Playwright)', dur: 140, note: 'Headless Chromium opens the built page, clicks through it and checks what it sees: 140 s.' },
    { id: 'deploy', name: 'Deploy', dur: 35, note: 'The deploy step uploads the build to the server. The workflow runs it only on main, never for a branch.' }
  ];
  const stations = [
    { id: 'dev', name: 'Developer', icon: 'laptop', role: 'Where the change is written and pushed. After `git push`, the developer does nothing until the check comes back.' },
    { id: 'github', name: 'GitHub', icon: 'git-branch', role: 'Receives the push, records the event, matches it against every workflow file under .github/workflows, and shows the result on the pull request.' },
    { id: 'runner', name: 'Actions runner', icon: 'server', role: 'A fresh virtual machine GitHub starts for this run. It has an operating system and nothing else; every tool the job needs is installed by a step.' },
    { id: 'pr', name: 'Pull request', icon: 'git-pull-request', role: 'The review page for the branch. The workflow\'s result appears here as a check; branch protection can make a green check a condition for merging.' },
    { id: 'server', name: 'Server', icon: 'cloud-upload', role: 'Where the deploy step puts the build. Only a run on main reaches it.' }
  ];
  const st = Object.fromEntries(STEPS.map(s => [s.id, 'queued']));
  let t = 0, real = 0, run = 'none', pr = toMain ? 'none' : 'open', deployed = null, merged = false, blocked = false;
  const scenes = [], events = [];
  const scene = (title, caption) => scenes.push({ i: scenes.length, title, caption, start: +t.toFixed(2) });
  const add = (station, kind, realMs, dur, note, extra) => {
    extra = extra || {};
    if (extra.step) st[extra.step] = extra.status;
    if (extra.run) run = extra.run;
    if (extra.pr) pr = extra.pr;
    if (extra.deployed) deployed = extra.deployed;
    if (extra.merged) merged = true;
    if (extra.blocked) blocked = true;
    events.push({ i: events.length, scene: scenes.length - 1, station, kind, realMs, start: +t.toFixed(2), dur, note, step: extra.step || null, fail: !!extra.fail,
      snap: { steps: Object.assign({}, st), run, pr, deployed, merged, blocked, realMs } });
    t += dur;
  };
  const runSteps = (label, offset, scenesBefore) => {
    // runs the workflow's steps in order; a failing step stops the job and every later step is skipped
    let clock = offset, failedAt = null;
    for (const s of STEPS) {
      if (scenesBefore && scenesBefore[s.id] && !failedAt) scene(scenesBefore[s.id][0], scenesBefore[s.id][1]);
      if (failedAt) { add('runner', 'skip', clock, 0.6, s.name + ' never runs: the job stopped at the first failing step.', { step: s.id, status: 'skipped' }); continue; }
      if (s.id === 'deploy' && !(toMain || merged)) { add('runner', 'skip', clock, 1.2, 'Deploy is skipped: this run is for a branch, and the step is conditional on main.', { step: s.id, status: 'skipped' }); continue; }
      add('runner', 'run', clock, Math.min(2.6, 1.1 + s.dur / 60), s.note, { step: s.id, status: 'running' });
      clock += s.dur * S;
      const failed = s.id === 'unit' && fails;
      st[s.id] = failed ? 'failed' : 'passed';
      if (failed) failedAt = s.id;
      if (s.id === 'deploy') { st.deploy = 'passed'; deployed = label; }
    }
    return { endMs: clock, failedAt };
  };

  scene('git push', 'A developer finishes a change on a branch and pushes it. ' + (toMain ? 'This time the push goes straight to main.' : 'The branch has an open pull request.'));
  add('dev', 'push', 0, 2.0, 'git push origin ' + (toMain ? 'main' : 'feature/export-course') + '. The commits leave the laptop. From here on, nothing runs on the developer\'s machine.');
  scene('GitHub receives the push', 'GitHub records a push event and looks for workflow files in .github/workflows. One of them says "on: [push, pull_request]", so a run is queued.');
  add('github', 'event', 2 * S, 2.0, 'Event: push to ' + (toMain ? 'main' : 'feature/export-course') + '. The file .github/workflows/test.yml matches, so GitHub queues a workflow run.', { run: 'queued' });
  scene('A fresh runner', 'GitHub starts a virtual machine for this run. It has Ubuntu and nothing else: no Node, no dependencies, no browser. Every step installs what the next one needs.');
  add('runner', 'start', 15 * S, 2.0, 'An Ubuntu runner picks up the job 15 s later. Empty disk, no Node, no browser, 30-minute budget.', { run: 'running' });
  scene(warm ? 'Install, from the cache' : 'Install, from scratch', warm ? 'The dependency and browser caches are warm, so the install steps take seconds.' : 'Nothing is cached, so npm ci and the Chromium download take the time they take. Later runs will reuse what this one downloads.');
  const first = runSteps(toMain ? 'main' : 'branch', 15 * S, {
    build: ['Build and test', 'The same commands a developer runs locally, now on a machine nobody configured by hand. A step that exits non-zero stops the job; the steps after it never run.'],
    e2e: ['Browser tests', 'Playwright drives headless Chromium through the built page. This is the longest step, and the one that catches what unit tests cannot.'] });
  let endMs = first.endMs;
  const fmt = ms => { const s = Math.round(ms / 1000); return s >= 60 ? Math.floor(s / 60) + ' min ' + String(s % 60).padStart(2, '0') + ' s' : s + ' s'; };
  if (toMain) {
    scene('The verdict', fails ? 'The job failed at the unit tests, so the deploy step never ran. Main is red, and the server still has the previous version.' : 'Every step passed and the deploy step ran. The server has the new build, ' + fmt(endMs) + ' after the push.');
    if (fails) add('github', 'red', endMs, 2.2, 'Run failed at "Unit tests" after ' + fmt(endMs) + '. The commit on main is marked red; the deploy step was skipped, so nothing broken reached the server.', { run: 'failed', fail: true });
    else add('server', 'live', endMs, 2.2, 'Run succeeded in ' + fmt(endMs) + '. The server is serving the new build.', { run: 'passed' });
  } else {
    scene('The verdict on the pull request', 'The run reports back to the pull request as a check. ' + (fails ? 'It is red.' : 'It is green.') + (protect ? ' Branch protection requires the check to pass before anyone can merge.' : ' Branch protection is off, so the merge button works either way.'));
    if (fails) {
      add('pr', 'red', endMs, 2.2, 'Check failed after ' + fmt(endMs) + ': "Unit tests" exited 1. The pull request shows a red cross and the failing assertion.', { run: 'failed', pr: 'red', fail: true });
      if (protect) { add('pr', 'blocked', endMs + 5 * S, 2.2, 'Merge blocked: branch protection requires the check. The developer fixes the test and pushes again, which starts a new run.', { pr: 'blocked', blocked: true }); endMs += 5 * S; }
      else {
        add('pr', 'merge', endMs + 4 * MIN, 2.0, 'Nothing stops the merge. A reviewer merges the red pull request four minutes later.', { pr: 'merged', merged: true });
        scene('The same workflow on main', 'The merge is itself a push to main, so the workflow runs again, and fails again at the same test. Deploy never runs.');
        add('github', 'event', endMs + 4 * MIN + 2 * S, 1.6, 'Push to main (the merge commit). A second run is queued.', { run: 'queued' });
        for (const s of STEPS) st[s.id] = 'queued';
        const second = runSteps('main', endMs + 4 * MIN + 15 * S);
        endMs = second.endMs;
        add('github', 'red', endMs, 2.2, 'The main run fails at "Unit tests" too. Main is red and the server keeps the previous version.', { run: 'failed', fail: true });
      }
    } else {
      add('pr', 'green', endMs, 2.2, 'Check passed in ' + fmt(endMs) + '. The pull request shows a green tick next to the commit.', { run: 'passed', pr: 'green' });
      add('pr', 'merge', endMs + 4 * MIN, 2.0, 'A reviewer merges the pull request four minutes later. The merge is a push to main.', { pr: 'merged', merged: true });
      scene('The same workflow on main', 'The merge commit triggers the workflow again, now on main, where the deploy step is allowed to run.');
      add('github', 'event', endMs + 4 * MIN + 2 * S, 1.6, 'Push to main (the merge commit). A second run is queued with the same workflow file.', { run: 'queued' });
      for (const s of STEPS) st[s.id] = 'queued';
      const second = runSteps('main', endMs + 4 * MIN + 15 * S);
      endMs = second.endMs;
      add('server', 'live', endMs, 2.2, 'The main run passes and deploys. The server has the new build ' + fmt(endMs) + ' after the first push.', { run: 'passed' });
    }
  }
  const soWhat = fails
    ? (toMain || protect ? 'So what: the workflow is the gate. A failing step stops the job before deploy, so a bad commit costs a red mark and a fix, not an outage.' : 'So what: without branch protection the check is advice, not a gate. The red pull request was merged, main went red, and only the conditional deploy step kept the server safe.')
    : (warm ? 'So what: a fresh machine every run is the guarantee, and caches are what make it affordable. Keyed on the lock file, they turn minutes of install into seconds.' : 'So what: the first run pays for everything it downloads. Cache the dependencies and the browser, keyed on the lock file, and the next run is minutes faster for the same guarantee.');
  scene('So what', soWhat);
  const stepsOut = STEPS.map(s => ({ id: s.id, name: s.name, dur: s.dur, status: st[s.id] }));
  const passed = stepsOut.filter(s => s.status === 'passed').length, skipped = stepsOut.filter(s => s.status === 'skipped').length, failed = stepsOut.filter(s => s.status === 'failed').length;
  const outcome = deployed ? 'Deployed to the server ' + fmt(endMs) + ' after the push, with ' + passed + ' steps passed on the final run.'
    : blocked ? 'Not deployed. The pull request is blocked by its red check after ' + fmt(endMs) + '; the fix will start a new run.'
    : merged ? 'Merged, but not deployed: main is red after ' + fmt(endMs) + ' and the deploy step was skipped.'
    : 'Not deployed. The run on main failed at "Unit tests" after ' + fmt(endMs) + '; the deploy step was skipped.';
  add('dev', 'outcome', endMs, 4.0, outcome);
  scenes.forEach((s, k) => { s.end = k < scenes.length - 1 ? scenes[k + 1].start : +t.toFixed(2); s.dur = +(s.end - s.start).toFixed(2); });
  return {
    target: toMain ? 'main' : 'branch', fails, warm, protect, stations, steps: stepsOut, scenes, events, duration: +t.toFixed(2), markers: scenes.map(s => s.start),
    installSeconds: STEPS[2].dur + STEPS[3].dur, totalMs: endMs, totalText: fmt(endMs), deployed: !!deployed, merged, blocked, passed, skipped, failed, outcome, soWhat,
    summary: (toMain ? 'Push to main' : 'Branch with a pull request') + ', ' + (warm ? 'warm' : 'cold') + ' cache, tests ' + (fails ? 'fail' : 'pass') + ': ' + (deployed ? 'deployed after ' + fmt(endMs) + '.' : blocked ? 'merge blocked by the red check.' : merged ? 'merged red; main failed, no deploy.' : 'run failed, no deploy.')
  };
}

checkCode:
function check(p) {
  const m = model(p), toMain = Math.round(p.target) === 1, fails = Math.round(p.test) === 1, warm = Math.round(p.cache) === 1, protect = Math.round(p.protection) === 1;
  const ordered = m.events.every((e, k) => !k || (e.realMs >= m.events[k - 1].realMs && e.start >= m.events[k - 1].start));
  const order = m.steps.map(s => s.id), i = id => order.indexOf(id);
  // a failing step stops the job: everything after it is skipped, everything before it passed
  const stepsOk = fails ? m.steps.every(s => i(s.id) < i('unit') ? s.status === 'passed' : s.id === 'unit' ? s.status === 'failed' : s.status === 'skipped')
    : m.steps.every(s => s.id === 'deploy' ? s.status === (toMain || m.merged ? 'passed' : 'skipped') : s.status === 'passed');
  const deployOk = m.deployed === (!fails && (toMain || m.merged));
  const gateOk = toMain ? (!m.merged && !m.blocked) : fails ? (m.blocked === protect && m.merged === !protect) : (m.merged && !m.blocked);
  const cold = model(Object.assign({}, p, { cache: 0 })), hot = model(Object.assign({}, p, { cache: 1 }));
  const cacheOk = hot.installSeconds < cold.installSeconds && hot.totalMs < cold.totalMs;
  return {
    pass: ordered && stepsOk && deployOk && gateOk && cacheOk,
    detail: m.passed + ' steps passed, ' + m.failed + ' failed, ' + m.skipped + ' skipped on the final run; ' + (m.deployed ? 'deployed after ' + m.totalText : 'not deployed') +
      (toMain ? '' : m.blocked ? '; merge blocked by branch protection' : m.merged ? '; merged' + (fails ? ' despite the red check' : ' on green') : '') +
      '; install takes ' + hot.installSeconds + ' s warm against ' + cold.installSeconds + ' s cold; ' + m.events.length + ' events in time order' + (ordered ? '.' : ' (NOT).')
  };
}
